[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/contact/MessageStore.java", "content": "package com.example.contact;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import com.vaadin.flow.server.VaadinSession;

/**
 * Keeps the messages that have been sent, newest first. The store lives in the
 * Vaadin session, so the list survives leaving a view and coming back to it.
 */
public class MessageStore implements Serializable {

    private final List<Message> messages = new ArrayList<>();

    /**
     * Returns the store of the current session, creating it on first use.
     */
    public static MessageStore get() {
        VaadinSession session = VaadinSession.getCurrent();
        if (session == null) {
            // No session at hand (unit test or background thread): give a
            // throw-away store rather than failing.
            return new MessageStore();
        }
        MessageStore store = session.getAttribute(MessageStore.class);
        if (store == null) {
            store = new MessageStore();
            session.setAttribute(MessageStore.class, store);
        }
        return store;
    }

    /**
     * Adds a message as the newest one.
     */
    public synchronized void add(Message message) {
        messages.add(0, message);
    }

    /**
     * All messages sent so far, newest first.
     */
    public synchronized List<Message> all() {
        return Collections.unmodifiableList(new ArrayList<>(messages));
    }
}
