+
+    private Locator heading() {
+        return page.locator("h1");
+    }
+
+    /** Only an open dialog carries the dialog role. */
+    private Locator openDialog() {
+        return page.getByRole(AriaRole.DIALOG);
+    }
+
+    private Locator cellContent(GridElement grid, int row, int column) {
+        return grid.findCell(row, column).orElseThrow()
+                .getCellContentLocator();
+    }
+
+    @Test
+    void view_showsHeadingLinkAndForm() {
+        assertThat(heading()).hasText("Contact");
+        assertThat(aboutLink()).isVisible();
+        assertThat(name().getLocator()).isVisible();
+        assertThat(email().getLocator()).isVisible();
+        assertThat(phone().getLocator()).isVisible();
+        assertThat(message().getLocator()).isVisible();
+        send().assertEnabled();
+    }
+
+    @Test
+    void emptyForm_showsTheErrors() {
+        send().click();
+
+        name().assertErrorMessage("Name is required");
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertErrorMessage("Message is required");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+        send().assertEnabled();
+    }
+
+    @Test
+    void malformedEmail_showsTheError() {
+        name().setValue("Ada");
+        email().setValue("not-an-address");
+        message().setValue("Hello");
+
+        send().click();
+
+        email().assertErrorMessage("Enter a valid e-mail address");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+        name().assertValue("Ada");
+    }
+
+    @Test
+    void tooLongMessage_showsTheError() {
+        name().setValue("Ada");
+        phone().setValue("123");
+        message().setValue("x".repeat(501));
