+        email().setValue("ada@example.com");
+        message().setValue("Hello there");
+
+        send().click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        GridElement grid = GridElement.get(page);
+        assertThat(cellContent(grid, 0, 0)).hasText("Ada");
+        assertThat(cellContent(grid, 0, 1)).hasText("Hello there");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertDisabled();
+
+        name().setValue("Someone else");
+        send().assertEnabled();
+    }
+
+    @Test
+    void enter_sendsTheMessage() {
+        name().setValue("Ada");
+        phone().setValue("555");
+        message().setValue("Sent with Enter");
+        message().getInputLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(cellContent(GridElement.get(page), 0, 1))
+                .hasText("Sent with Enter");
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAskingAndWithoutReloading() {
+        page.evaluate("window.__notReloaded = true");
+
+        aboutLink().click();
+
+        assertThat(heading()).hasText("About");
+        assertEquals(Boolean.TRUE, page.evaluate("window.__notReloaded"),
+                "navigation happened without a page reload");
+        assertThat(openDialog()).hasCount(0);
+    }
+
+    @Test
+    void leavingWithSomethingTyped_asksFirst() {
+        name().setValue("Ada");
+        message().setValue("Half written");
+
+        aboutLink().click();
+
+        assertThat(openDialog()).hasCount(1);
+
+        ButtonElement.getByText(page, "Keep editing").click();
+        assertThat(heading()).hasText("Contact");
+        name().assertValue("Ada");
+        message().assertValue("Half written");
+
+        aboutLink().click();
+        assertThat(openDialog()).hasCount(1);
+        ButtonElement.getByText(page, "Discard").click();
+        assertThat(heading()).hasText("About");
+    }
+}
